'use strict';
const express=require('express'),crypto=require('crypto'),fs=require('fs'),path=require('path'),multer=require('multer'),{spawn}=require('child_process');
const{db}=require('../db'),{DATA_DIR,APP_DIR}=require('../paths'),{renderFilm}=require('../filmMedia.cjs');
const router=express.Router(),dir=path.join(DATA_DIR,'videos');fs.mkdirSync(dir,{recursive:true});
db.exec('CREATE TABLE IF NOT EXISTS video_tool_clips(id TEXT PRIMARY KEY,name TEXT NOT NULL,filename TEXT NOT NULL,duration REAL NOT NULL);CREATE TABLE IF NOT EXISTS video_tool_exports(id TEXT PRIMARY KEY,payload TEXT NOT NULL)');
function binary(){return require(path.join(APP_DIR,'vendor/media/node_modules/ffmpeg-static')).replace(/app\.asar([/\\])/,'app.asar.unpacked$1')}
function probe(file){return new Promise((resolve,reject)=>{const p=spawn(binary(),['-hide_banner','-i',file],{stdio:['ignore','ignore','pipe']});let text='';const timer=setTimeout(()=>p.kill('SIGKILL'),15000);p.stderr.on('data',b=>text=(text+b).slice(-20000));p.on('error',e=>{clearTimeout(timer);reject(e)});p.on('close',()=>{clearTimeout(timer);const d=text.match(/Duration:\s*(\d+):(\d+):(\d+(?:\.\d+)?)/);if(!d||!/Video:/.test(text))return reject(Error('Clip không có video hợp lệ.'));const duration=Number(d[1])*3600+Number(d[2])*60+Number(d[3]);if(!Number.isFinite(duration)||duration<=0||duration>600)return reject(Error('Mỗi clip tối đa 10 phút.'));resolve(duration)})})}
function save(p){db.prepare('INSERT OR REPLACE INTO video_tool_exports(id,payload) VALUES(?,?)').run(p.id,JSON.stringify(p));return p}
function clip(id){const upload=db.prepare('SELECT * FROM video_tool_clips WHERE id=?').get(id);if(upload)return{...upload,file:path.join(dir,path.basename(upload.filename)),url:'/videos/'+upload.filename};const row=db.prepare("SELECT id,prompt AS name,video_url AS url,duration FROM jobs WHERE id=? AND status='completed' AND media_type='video'").get(id);if(!row||!/^\/videos\/[^/]+\.(mp4|webm|mov)$/i.test(row.url||''))throw Error('Clip không còn trong thư viện.');return{...row,file:path.join(dir,path.basename(row.url))}}
router.get('/clips',(_,res)=>{const uploads=db.prepare('SELECT * FROM video_tool_clips ORDER BY rowid DESC LIMIT 100').all().map(r=>({id:r.id,name:r.name,url:'/videos/'+r.filename,duration:r.duration})),jobs=db.prepare("SELECT id,prompt AS name,video_url AS url,duration,thumbnail_url FROM jobs WHERE status='completed' AND media_type='video' AND archived_at IS NULL ORDER BY created_at DESC LIMIT 100").all().filter(j=>/^\/videos\/[^/]+\.(mp4|webm|mov)$/i.test(j.url||''));res.json({clips:[...uploads,...jobs]})});
router.use((req,res,next)=>{const origin=req.get('origin');if(origin&&!['http://localhost:'+req.socket.localPort,'http://127.0.0.1:'+req.socket.localPort].includes(origin))return res.status(403).json({error:'Nguồn yêu cầu không hợp lệ.'});next()});
const upload=multer({storage:multer.diskStorage({destination:dir,filename:(_req,file,done)=>done(null,'clip_'+crypto.randomUUID()+(/\.webm$/i.test(file.originalname)?'.webm':/\.mov$/i.test(file.originalname)?'.mov':'.mp4'))}),limits:{fileSize:200*1024*1024,files:1},fileFilter:(_req,file,done)=>done(null,/\.(mp4|mov|webm)$/i.test(file.originalname))}).single('file');
router.post('/upload',(req,res)=>upload(req,res,async error=>{if(error)return res.status(400).json({error:'Clip tối đa 200 MB.'});try{if(!req.file)throw Error('Chọn MP4, MOV hoặc WebM.');const duration=await probe(req.file.path),row={id:'clip_'+crypto.randomUUID(),name:path.basename(req.file.originalname).slice(0,160),filename:req.file.filename,duration};db.prepare('INSERT INTO video_tool_clips(id,name,filename,duration) VALUES(?,?,?,?)').run(row.id,row.name,row.filename,row.duration);res.json({...row,url:'/videos/'+row.filename})}catch(e){if(req.file)fs.rmSync(req.file.path,{force:true});res.status(400).json({error:e.message})}}));
let busy=false;
router.get('/exports',(_,res)=>res.json({exports:db.prepare('SELECT payload FROM video_tool_exports ORDER BY rowid DESC LIMIT 20').all().map(r=>JSON.parse(r.payload))}));
router.get('/exports/:id',(req,res)=>{const row=db.prepare('SELECT payload FROM video_tool_exports WHERE id=?').get(req.params.id);if(!row)return res.status(404).json({error:'Không tìm thấy bản ghép.'});res.json(JSON.parse(row.payload))});
router.post('/merge',async(req,res)=>{if(busy)return res.status(409).json({error:'Đang ghép một video khác. Vui lòng chờ hoàn tất.'});let work,out;try{const body=req.body||{};if(!Array.isArray(body.clips)||body.clips.length<2||body.clips.length>8)throw Error('Chọn từ 2 đến 8 clip.');if(!['16:9','9:16','1:1'].includes(body.ratio))throw Error('Khung hình không hợp lệ.');if(!['cut','fade'].includes(body.transition))throw Error('Chuyển cảnh không hợp lệ.');busy=true;const clips=[];for(const selected of body.clips){const row=clip(String(selected.id));if(!fs.existsSync(row.file))throw Error('Clip không còn trên máy.');const length=await probe(row.file),start=selected.start===undefined?0:Number(selected.start),end=selected.end===undefined?length:Number(selected.end);if(!Number.isFinite(start)||!Number.isFinite(end)||start<0||end>length+.05||end-start<.5||end-start>120)throw Error('Mỗi đoạn chọn từ 0,5 đến 120 giây, trong thời lượng clip.');clips.push({file:row.file,start,duration:end-start})}if(clips.reduce((n,c)=>n+c.duration,0)>300)throw Error('Tổng video tối đa 5 phút.');const id='merge_'+crypto.randomUUID(),entry=save({id,status:'running',progress:0,ratio:body.ratio,createdAt:new Date().toISOString()});work=fs.mkdtempSync(path.join(dir,'merge_work_'));out=path.join(dir,id+'.mp4');res.status(202).json(entry);
(async()=>{try{const result=await renderFilm({ffmpeg:binary(),clips,out,work,ratio:body.ratio,transition:body.transition,audio:body.audio!==false,onProgress:n=>{entry.progress=n;save(entry)}});entry.status='completed';entry.progress=100;entry.url='/videos/'+id+'.mp4';entry.duration=result.duration;entry.savedTo=require('../dispatcher').saveVideoToComputer(id,'Ghép '+clips.length+' clip',entry.url);db.prepare("INSERT INTO jobs(id,prompt,ref_tags,media_type,status,progress,duration,ratio,attempts,max_retries,timeout_minutes,sort_order,created_at,finished_at,video_url) VALUES(?,?,'[]','video','completed',100,?,?,0,0,3,0,datetime('now'),datetime('now'),?)").run(id,'Ghép '+clips.length+' clip',result.duration,body.ratio,entry.url);save(entry)}catch(e){entry.status='failed';entry.error=e.message;save(entry);fs.rmSync(out,{force:true})}finally{fs.rmSync(work,{recursive:true,force:true});busy=false}})();
}catch(e){busy=false;if(work)fs.rmSync(work,{recursive:true,force:true});if(!res.headersSent)res.status(400).json({error:e.message})}});
for(const row of db.prepare('SELECT payload FROM video_tool_exports').all()){const e=JSON.parse(row.payload);if(e.status==='running'){e.status='failed';e.error='App đã đóng trong khi ghép. Chọn clip và ghép lại.';save(e)}}
module.exports={router,probe};
